import{_ as o,a0 as r,w as l,s as d,I as e,x as n,a1 as t,A as i,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"利用 DNS SRV 记录为 Postfix 提供负载平衡 | LCTT x X-CMD","titleTemplate":false,"description":"利用 DNS SRV 记录为 Postfix 提供负载平衡 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"利用 DNS SRV 记录为 Postfix 提供负载平衡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"利用 DNS SRV 记录为 Postfix 提供负载平衡 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20230616 Using Postfix DNS SRV record resolution feature","title":"利用 DNS SRV 记录为 Postfix 提供负载平衡","tag":"202312","desc":""},"relativePath":"202312/20230616 Using Postfix DNS SRV record resolution feature.md","filePath":"[post].md"}'),c={name:"202312/20230616 Using Postfix DNS SRV record resolution feature.md"};function h(u,s,f,m,g,b){const a=r("Link");return l(),d("div",null,[s[24]||(s[24]=e("h1",{id:"利用-dns-srv-记录为-postfix-提供负载平衡",tabindex:"-1"},[n("利用 DNS SRV 记录为 Postfix 提供负载平衡 "),e("a",{class:"header-anchor",href:"#利用-dns-srv-记录为-postfix-提供负载平衡","aria-label":"Permalink to “利用 DNS SRV 记录为 Postfix 提供负载平衡”"},"​")],-1)),s[25]||(s[25]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202312/15/173522hpze31p331ppljrj.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=n("2011 年 3 月，苹果公司提出 ",-1)),t(a,{href:"https://www.ietf.org/rfc/rfc6186.txt"},{default:i(()=>[...s[0]||(s[0]=[n("RFC 6186",-1)])]),_:1}),s[2]||(s[2]=n("，描述了如何利用域名系统服务（DNS SRV）记录来查找电子邮件的提交以及访问服务。现在 Postfix 从 3.8.0 版本开始支持 RFC 中提出的设计。这个新增功能让你可以使用 DNS SRV 记录进行负载分配和自动配置。",-1))]),s[26]||(s[26]=e("h3",{id:"dns-srv-记录的形态",tabindex:"-1"},[n("DNS SRV 记录的形态 "),e("a",{class:"header-anchor",href:"#dns-srv-记录的形态","aria-label":"Permalink to “DNS SRV 记录的形态”"},"​")],-1)),e("p",null,[s[4]||(s[4]=n("DNS SRV 记录定义在 ",-1)),t(a,{href:"https://www.ietf.org/rfc/rfc2782.txt"},{default:i(()=>[...s[3]||(s[3]=[n("RFC 2782",-1)])]),_:1}),s[5]||(s[5]=n(" 中，它指定在区域文件中，并且包含了服务名称、传输协议规范、优先级、权重、端口，以及提供该服务的主机。",-1))]),s[27]||(s[27]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>_submission._tcp    SRV 5 10 50 bruce.my-domain.com.</span></span></code></pre></div><div class="table-wrap"><table><thead><tr><th>字段</th><th>值</th><th>意义</th></tr></thead><tbody><tr><td>服务名称</td><td><code>submission</code></td><td>服务名为 submission</td></tr><tr><td>传输协议规范</td><td><code>tcp</code></td><td>本服务使用 TCP 协议</td></tr><tr><td>优先级</td><td><code>5</code></td><td>服务器优先级设为 5（数值越小，优先级越高）</td></tr><tr><td>权重</td><td><code>10</code></td><td>服务器应承担的负载部分</td></tr><tr><td>端口</td><td><code>50</code></td><td>服务器监听连接的端口</td></tr><tr><td>目标</td><td><code> bruce.my-domain.com.</code></td><td>提供此服务的服务器名称</td></tr></tbody></table></div><p><em>记录解释</em></p><h3 id="服务器选择算法" tabindex="-1">服务器选择算法 <a class="header-anchor" href="#服务器选择算法" aria-label="Permalink to “服务器选择算法”">​</a></h3>',4)),e("p",null,[s[7]||(s[7]=n("客户端应该按照 ",-1)),t(a,{href:"https://www.ietf.org/rfc/rfc2782.txt"},{default:i(()=>[...s[6]||(s[6]=[n("RFC 2782",-1)])]),_:1}),s[8]||(s[8]=n(" 中描述的方式解析 SRV 记录。这意味着，首先尝试联系拥有最高优先级（最小的优先级数字）的服务器。如果该服务器无回应，那么重试联系拥有同样或者更低优先级的下一台服务器。当有多台服务器拥有同样优先级的时候，应随机选择其中一台，但是必须确保选择记录的概率符合下列公式：",-1))]),s[28]||(s[28]=p(`<p><img src="https://fedoramagazine.org/wp-content/uploads/2023/06/probability_equation.png" alt=""></p><p>其中 <code>i</code> 是 SRV 记录的标识，<code>k</code> 是具有相同优先级的 SRV 记录的数量。</p><p>在现实中，这意味着如果你有两台服务器，其中一台的处理能力是另一台的三倍，那么你应该给第一台服务器的权重赋于另一台三倍的值。这样就能保证更强大的服务器会接收到大约 75% 的客户端请求，而另一台接收大约 25% 的请求。</p><p>这些原则使得 SRV 记录能够同时作为客户端自动配置及在服务器之间分配工作负载的工具。</p><p>看看以下这个记录的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>_submission._tcp     SRV 0 0 2525 server-one</span></span>
<span class="line"><span>_submission._tcp     SRV 1 75 2625 server-two</span></span>
<span class="line"><span>_submission._tcp     SRV 1 25 2625 server-three</span></span></code></pre></div><p>这里 <code>server-one</code> 总是会被首选来进行联系。如果 <code>server-one</code> 无回应，客户端就会将剩下优先级为 1 的两个记录顺序打乱，生成一个从 0 到 100 的随机数，如果第一条记录的运行总和大于或者等于这个随机数，它就会尝试去联系这个记录。否则，客户端会倒序联系所有服务器。注意，客户端会向它优先成功连接的服务器发送请求。</p><h3 id="示例配置" tabindex="-1">示例配置 <a class="header-anchor" href="#示例配置" aria-label="Permalink to “示例配置”">​</a></h3><p>请考虑以下这种情况。你想为大量的电脑配置 Postfix，使其通过公司的邮件服务器利用 SRV 记录转发外部电邮。为了达到这个目标，你需要在每台电脑的 Postfix 中配置 <code>relayhost</code> 参数，即邮件用户代理（MUA）。如果将 <code>relayhost</code> 参数的值设置为 <code>$mydomain</code>，你的机器将开始为你的域名查找 MX 记录，并尝试按照它们的优先级顺序发送邮件。这种方法虽然有效，但是可能会遇到负载平衡问题。Postfix 会使用优先级最高的服务器，直到其变为无响应才会联系其他备用服务器。此外，如果你在环境中使用了动态分配的端口，你无法指明哪个端口正在被特定的服务器使用。使用 SRV 记录，你可以应对这些挑战，并在需要改变服务器端口的时候维持服务器的平滑运行。</p><h4 id="区域文件" tabindex="-1">区域文件 <a class="header-anchor" href="#区域文件" aria-label="Permalink to “区域文件”">​</a></h4><p>为了使得 DNS 服务器提供信息给客户端，可以参考以下使用服务器 <code>server-one</code>、<code>server-two</code>、<code>server-three</code> 作为中继，并把服务器 <code>server-four</code> 配置为接收测试邮件的区域文件示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$TTL  3600</span></span>
<span class="line"><span>@       IN SOA  example-domain.com. root.example-domain.com. (</span></span>
<span class="line"><span>                1571655122 ; 区域文件的序列号</span></span>
<span class="line"><span>                1200       ; 刷新时间</span></span>
<span class="line"><span>                180        ; 发生问题时的重试时间</span></span>
<span class="line"><span>                1209600    ; 过期时间</span></span>
<span class="line"><span>                10800 )    ; 查询失败时的最大缓存时间</span></span>
<span class="line"><span>;</span></span>
<span class="line"><span>        IN NS   ns1</span></span>
<span class="line"><span>        IN A    192.168.2.0</span></span>
<span class="line"><span>;</span></span>
<span class="line"><span>ns1     IN A    192.168.2.2</span></span>
<span class="line"><span>server-one           IN A   192.168.2.4</span></span>
<span class="line"><span>server-two           IN A   192.168.2.5</span></span>
<span class="line"><span>server-three         IN A   192.168.2.6</span></span>
<span class="line"><span>server-four          IN A   192.168.2.7</span></span>
<span class="line"><span>_submission._tcp     SRV 0 0 2525  server-one</span></span>
<span class="line"><span>_submission._tcp     SRV 1 50 2625 server-two</span></span>
<span class="line"><span>_submission._tcp     SRV 1 50 2625 server-three</span></span>
<span class="line"><span>@ MX 0 server-four</span></span></code></pre></div><h4 id="postfix-mua-配置" tabindex="-1">Postfix MUA 配置 <a class="header-anchor" href="#postfix-mua-配置" aria-label="Permalink to “Postfix MUA 配置”">​</a></h4><p>设置客户端机器去查找 SRV 记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>use_srv_lookup = submission</span></span>
<span class="line"><span>relayhost = example-domain.com:submission</span></span></code></pre></div><p>通过这个配置，你的客户端机器上的 Postfix 实例会联络到 <code>example-domain</code> 的 DNS 服务器，然后获取邮件提交的 SRV 记录。在这个例子中，<code>server-one</code> 有最高的优先级，Postfix 会先试图连接它。然后，Postfix 随机的选择剩下的两个服务器其中一个去尝试连接。这个配置确保了大约有 50% 的机会会优先联系到服务器一。注意，SRV 记录的权重值并不等同于百分比。你也可以用 1 和 1 这样的值达到同样的目标。</p><p>同时，Postfix 也知道 <code>server-one</code> 在监听 2525 端口，而 <code>server-two</code> 在监听 2625 端口。如果你正在缓存检索到的 DNS 记录，并且你动态改变 SRV 记录，那么设置一个低的生存时间（TTL）对你的记录是很重要的。</p><h4 id="整套设置" tabindex="-1">整套设置 <a class="header-anchor" href="#整套设置" aria-label="Permalink to “整套设置”">​</a></h4><p><img src="https://fedoramagazine.org/wp-content/uploads/2023/06/srv_article.png" alt=""></p><p>你可以通过下面的方式尝试这个配置，包含 podman 和在此处提供的 compose 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/TomasKorbar/srv_article</span></span>
<span class="line"><span>$ cd srv_article/environment</span></span>
<span class="line"><span>$ podman-compose up</span></span>
<span class="line"><span>$ podman exec -it article_client /bin/bash</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # exit</span></span></code></pre></div><p>完成配置之后，你可以检查日志，查看邮件是否经过 <code>server-one</code> 并最终投递到 <code>server-four</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman stop article_server1</span></span>
<span class="line"><span>$ podman exec -it article_client /bin/bash</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # ./senddummy.sh</span></span>
<span class="line"><span>root@client # exit</span></span></code></pre></div><p>现在 <code>server-one</code> 已经关闭了，这六封邮件将会由 <code>server-two</code> 或者 <code>server-three</code> 中转发出去。</p><p>仔细看一下 Dockerfiles 以更深地理解这个配置。</p><p>通过执行：<code>$ podman-compose down</code> 完成示例的操作。</p><p><em>（题图：DA/241079fe-58d6-4dc6-8801-f0fd19dfd64b）</em></p><hr>`,28)),e("p",null,[s[10]||(s[10]=n("via: ",-1)),t(a,{href:"https://fedoramagazine.org/using-postfix-dns-srv-record-resolution-feature/"},{default:i(()=>[...s[9]||(s[9]=[n("https://fedoramagazine.org/using-postfix-dns-srv-record-resolution-feature/",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=n("作者：",-1)),t(a,{href:"https://fedoramagazine.org/author/tkorbar/"},{default:i(()=>[...s[11]||(s[11]=[n("Tomáš Korbař",-1)])]),_:1}),s[16]||(s[16]=n(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[12]||(s[12]=[n("lujun9972",-1)])]),_:1}),s[17]||(s[17]=n(" 译者：",-1)),t(a,{href:"https://linux.cn/lctt/ChatGPT"},{default:i(()=>[...s[13]||(s[13]=[n("ChatGPT",-1)])]),_:1}),s[18]||(s[18]=n(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[14]||(s[14]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...s[20]||(s[20]=[n("Linux中国",-1)])]),_:1}),s[23]||(s[23]=n(" 荣誉推出",-1))])])}const v=o(c,[["render",h]]);export{S as __pageData,v as default};
